// Calcula saludo y horario laboral (TZ America/Guayaquil = UTC-5)
const now = new Date();
const guayaquil = new Date(now.toLocaleString('en-US', {timeZone: 'America/Guayaquil'}));
const h = guayaquil.getHours();
const m = guayaquil.getMinutes();
const dow = guayaquil.getDay(); // 0=Dom 6=Sáb

let saludo;
if (h >= 2 && h < 12) saludo = 'Buenos días';
else if (h >= 12 && h < 19) saludo = 'Buenas tardes';
else saludo = 'Buenas noches';

// Lun(1)–Vie(5) 08:30–17:30
const minutos = h * 60 + m;
const enHorario = dow >= 1 && dow <= 5 && minutos >= 510 && minutos < 1050;

return [{json: {
  ...items[0].json,
  saludo,
  is_horario_laboral: enHorario
}}];

// Determina escenario: 1=cliente asignado respondiendo, 2=desconocido/otro número
const item = items[0].json;
const isAssigned = item.is_assigned === true;

// Detectar si viene un button_reply (interacción de menú) o texto libre
const buttonId = item.button_reply_id || null;
const estado = item.estado_actual || 'NUEVO';

let scenario;
if (estado !== 'NUEVO' && estado !== 'MENU_PRINCIPAL') {
  scenario = 'ESTADO_ACTIVO'; // continúa la conversación
} else if (isAssigned && !buttonId) {
  scenario = 'ESC1_ASIGNADO'; // cliente registrado responde directo
} else {
  scenario = 'ESC2_MENU'; // desconocido o pide menú
}

return [{json: {...item, scenario}}];

const d = items[0].json;
const nombre = d.nombre_cliente || 'Cliente';
const msg = `Hola ${nombre}. Gracias por comunicarte con nosotros. Su ejecutivo de renovación ha sido notificado y se pondrá en contacto con usted dentro de nuestro horario de atención.`;
return [{json: {...d, wa_message: msg, wa_to: d.phone, next_estado: 'RENOV_NOTIFICADO'}}];

