// Parsea texto libre con datos de renovación: nombre + cédula/RUC
const texto = (items[0].json.content || '').trim();
const cedRuc = texto.match(/\b(\d{10}|\d{13})\b/);
let docNum = cedRuc ? cedRuc[1] : null;
let docTipo = null;
let docValido = null;
if (docNum) {
  if (docNum.length === 10) { docTipo = 'CEDULA'; docValido = true; }
  else if (docNum.length === 13) { docTipo = 'RUC'; docValido = true; }
}
// Nombre: todo lo que no sea el número
const nombre = texto.replace(/\b\d{10,13}\b/g, '').replace(/\s+/g,' ').trim();

return [{json: {
  ...items[0].json,
  datos_capturados: {nombre: nombre || null, documento: docNum},
  documento_tipo: docTipo,
  documento_numero: docNum,
  documento_valido: docValido
}}];

