// Construye mensaje WhatsApp para el asesor con contexto del cliente
const d = items[0].json;
const asesor = d.asesor || {};
const asig = d.asig || {};

const nombre = asig.nombre_cliente || 'Cliente';
const placa = (asig.vehiculos?.[0]?.plate) || 'N/D';
const vehiculo = (asig.vehiculos?.[0]?.model) || 'N/D';
const vencimiento = (asig.contratos?.[0]?.endDate) || 'N/D';
const telefono = asig.telefono_e164 || d.phone || '';

const msg = `🔔 *Renovación QuickLink*\n\n`
  + `👤 Cliente: ${nombre}\n`
  + `📱 Teléfono: ${telefono}\n`
  + `🚗 Vehículo: ${vehiculo} (${placa})\n`
  + `📅 Vencimiento: ${vencimiento}\n\n`
  + `El cliente solicitó contacto con su ejecutivo.`;

return [{json: {
  ...d,
  wa_message_asesor: msg,
  wa_to_asesor: asesor.wa_number || ''
}}];

// Validate and normalize the campaign dispatch payload.
const body = items[0].json.body || items[0].json;
const dispatchId = body.dispatchId || ('DSP-' + Date.now());
const recipients = Array.isArray(body.recipients) ? body.recipients : [];

const templateId = body.templateId || body.template_id || null;
const templateName = body.templateName || body.template_name || templateId || null;
const metaWabaPhoneId = body.meta_waba_phone_id || body.metaWabaPhoneId || body.phone_number_id || null;
const metaToken = body.meta_token || body.metaToken || body.access_token || null;
const outboundBatchSize = Number(body.outbound_batch_size || body.outboundBatchSize || 25);

const valid = [];
const errors = [];
for (const r of recipients) {
  if (!r.phone || !r.customerId) {
    errors.push({customerId: r.customerId, error: 'missing phone or customerId'});
    continue;
  }

  const recipientTemplateId = r.templateId || r.template_id || templateId;
  const recipientTemplateName = r.templateName || r.template_name || recipientTemplateId || templateName;
  valid.push({
    ...r,
    dispatchId,
    campaignId: r.campaignId || r.campaign_id || body.campaignId,
    campaignName: r.campaignName || r.campaign_name || body.campaignName,
    advisorId: r.advisorId || r.advisor_id || body.advisorId,
    templateId: recipientTemplateId,
    templateName: recipientTemplateName,
    meta_waba_phone_id: r.meta_waba_phone_id || r.metaWabaPhoneId || r.phone_number_id || metaWabaPhoneId,
    meta_token: r.meta_token || r.metaToken || r.access_token || metaToken,
  });
}

return [{json: {
  dispatchId,
  campaignId: body.campaignId,
  campaignName: body.campaignName,
  segmentMonth: body.segmentMonth,
  advisorId: body.advisorId,
  templateId,
  templateName,
  meta_waba_phone_id: metaWabaPhoneId,
  meta_token: metaToken,
  outbound_batch_size: outboundBatchSize,
  valid_recipients: valid,
  errors,
  total: recipients.length
}}];

