BEGIN
  FOR r IN SELECT jsonb_array_elements($1::JSONB) LOOP
    INSERT INTO renov_asignaciones (telefono_e164, customer_id, advisor_id, is_assigned, marca, segment_month, campaign_id, updated_at)
    VALUES (r->>'phone', r->>'customerId', r->>'assignedAdvisorId', (r->>'isAssigned')::BOOLEAN, $2, $3, $2, NOW())
    ON CONFLICT (telefono_e164) DO UPDATE SET advisor_id=EXCLUDED.advisor_id, is_assigned=EXCLUDED.is_assigned, segment_month=EXCLUDED.segment_month, updated_at=NOW();
  END LOOP;
END $$;
SELECT COUNT(*) as upserted FROM renov_asignaciones WHERE campaign_id=$2;

