// Build a guarded WhatsApp template payload for Meta Graph API.
const r = items[0].json;
const mf = r.mergeFields || {};

function brandFrom(...values) {
  const raw = values.map(v => String(v || '').toUpperCase()).join(' ');
  if (raw.includes('HYUNDAI')) return 'HYUNDAI';
  if (raw.includes('KIA')) return 'KIA';
  return '';
}

function firstText(keys, fallback) {
  for (const key of keys) {
    const value = mf[key] ?? r[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') return String(value);
  }
  return fallback;
}

const brand = brandFrom(r.marca, r.brand, r.vehicle_brand, r.campaignId, r.campaign_id, r.campaignName, r.campaign_name);
const defaultTemplateByBrand = {
  KIA: 'kia_bienvenida_intro_v4_1',
  HYUNDAI: 'hyundai_bienvenida_intro_v4_2',
};

const approvedTemplates = {
  kia_bienvenida_intro_v4_1: { brand: 'KIA', lang: 'es', fields: ['nombre', 'modelo'] },
  kia_bienvenida_intro_v4_2: { brand: 'KIA', lang: 'es', fields: ['nombre', 'modelo'] },
  kia_bienvenida_intro_v4_3: { brand: 'KIA', lang: 'es', fields: ['nombre', 'modelo'] },
  kia_bienvenida_cta_v4_1: { brand: 'KIA', lang: 'es', fields: [] },
  kia_bienvenida_cta_v4_2: { brand: 'KIA', lang: 'es', fields: [] },
  kia_bienvenida_cta_v4_3: { brand: 'KIA', lang: 'es', fields: [] },
  hyundai_bienvenida_intro_v4_2: { brand: 'HYUNDAI', lang: 'es', fields: ['nombre', 'modelo'] },
  hyundai_bienvenida_intro_v4_3: { brand: 'HYUNDAI', lang: 'es', fields: ['nombre', 'modelo'] },
  hyundai_bienvenida_cta_v4_2: { brand: 'HYUNDAI', lang: 'es', fields: [] },
  hyundai_bienvenida_cta_v4_3: { brand: 'HYUNDAI', lang: 'es', fields: [] },
  kia_contacto2_v1: { brand: 'KIA', lang: 'es' },
  kia_contacto2_v2: { brand: 'KIA', lang: 'es' },
  kia_contacto2_v3: { brand: 'KIA', lang: 'es' },
  kia_contacto3_v1: { brand: 'KIA', lang: 'es' },
  kia_contacto3_v2: { brand: 'KIA', lang: 'es' },
  kia_contacto3_v3: { brand: 'KIA', lang: 'es' },
  hyundai_contacto2_v1: { brand: 'HYUNDAI', lang: 'es' },
  hyundai_contacto2_v2: { brand: 'HYUNDAI', lang: 'es' },
  hyundai_contacto2_v3: { brand: 'HYUNDAI', lang: 'es' },
  hyundai_contacto3_v1: { brand: 'HYUNDAI', lang: 'es' },
  hyundai_contacto3_v2: { brand: 'HYUNDAI', lang: 'es' },
  hyundai_contacto3_v3: { brand: 'HYUNDAI', lang: 'es' },
};

let requestedTemplate = String(r.templateName || r.template_name || r.templateId || r.template_id || '').trim();
if (!requestedTemplate || requestedTemplate === 'recordatorio_renovacion_generico') {
  requestedTemplate = defaultTemplateByBrand[brand] || '';
}

const tpl = approvedTemplates[requestedTemplate];
if (!tpl) {
  throw new Error(`[REN TEMPLATE GUARD] Template "${requestedTemplate || '(empty)'}" is not in the approved REN allowlist. campaignId=${r.campaignId || r.campaign_id || ''} customerId=${r.customerId || ''}`);
}
if (!brand || tpl.brand !== brand) {
  throw new Error(`[REN TEMPLATE GUARD] Template "${requestedTemplate}" belongs to ${tpl.brand}, but dispatch brand is ${brand || '(empty)'}. campaignId=${r.campaignId || r.campaign_id || ''} customerId=${r.customerId || ''}`);
}

let parameters = [];
if (Array.isArray(tpl.fields)) {
  if (tpl.fields.includes('nombre')) {
    parameters.push({type: 'text', text: firstText(['nombre_cliente', 'nombre', 'customerName', 'customer_name'], 'Cliente')});
  }
  if (tpl.fields.includes('modelo')) {
    parameters.push({type: 'text', text: firstText(['modelo', 'vehicle_model', 'model'], 'su vehiculo')});
  }
} else {
  parameters = Object.values(mf).map(v => ({type: 'text', text: String(v)}));
}

const template = {
  name: requestedTemplate,
  language: {code: tpl.lang},
};
if (parameters.length > 0) {
  template.components = [{type: 'body', parameters}];
}

return [{json: {
  ...r,
  templateId: requestedTemplate,
  templateName: requestedTemplate,
  template_name_used: requestedTemplate,
  wa_payload: {
    messaging_product: 'whatsapp',
    to: r.phone,
    type: 'template',
    template,
  }
}}];

// Valida y normaliza el payload del assignment sync
const body = items[0].json.body || items[0].json;
const assignments = body.assignments || [];
const syncId = body.syncId || ('SYNC-' + Date.now());

return [{json: {
  syncId,
  campaignId: body.campaignId,
  assignments: assignments.filter(a => a.phone && a.customerId)
}}];

